package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** 8-bit bundled data medium. Runtime payload; no 256-way BlockState explosion. */
public class EightBitDataBusBlock extends Block{public EightBitDataBusBlock(Properties p){super(p);}@Override public MapCodec<EightBitDataBusBlock> codec(){return RedstoneEngineering.EIGHT_BIT_DATA_BUS_CODEC.value();}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)DataBusNetwork.resolve(sl,DataBusNetwork.collect(sl,p));}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block nb,BlockPos np,boolean m){if(l instanceof ServerLevel sl)DataBusNetwork.resolve(sl,DataBusNetwork.collect(sl,p));}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("8-bit Bus = "+DataBusNetwork.sample(l,p)+" (0x"+String.format("%02X",DataBusNetwork.sample(l,p))+") | "+NetworkKernel.summary(l,"bus8")),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
